memo1 = {}
memo2 = {}

def count_num1(k):
    if k < 0:
        return 0
    elif k < 2:
        return 1
    elif k not in memo1:
        total_sum = 0
        for index in range(k):
            total_sum += count_num1(index) * count_num1(k - 1 - index)
        memo1[k] = total_sum
    return memo1[k]

def count_num2(k, m):
    if k < 0 or m <= 0 or k >= 2 ** (m - 1):
        return 0
    elif k < 2:
        return 1
    elif k < m:
        return count_num1(k)
    elif (k, m) not in memo2:
        total_sum = 0
        for index in range(k):
            total_sum += count_num2(index, m - 1) * count_num2(k - 1 - index, m - 1)
        memo2[(k, m)] = total_sum
    return memo2[(k, m)]

val1, val2 = map(int, raw_input().split())
print count_num1(val1) - count_num2(val1, val2)
